{"content":"# ============================================================
# Tolerant multi-file env loader for Erebus
# Does NOT delete or rewrite .env files — only reads them.
# Loads (later overrides earlier): advanced_agent/.env → LifeOS root .env → Hermes .env
# Also aliases VITE_* / typo keys into the names router/tools expect.
# ============================================================

from __future__ import annotations

import os
import re
from pathlib import Path

_LOADED = False

ROOT = Path(__file__).resolve().parent.parent  # advanced_agent/
LIFEOS_ROOT = ROOT.parent
HERMES_ENV = Path(os.environ.get("LOCALAPPDATA", "")) / "hermes" / ".env"

# Bare name ← candidates (first non-empty wins when aliasing)
ALIASES: dict[str, list[str]] = {
    "GROQ_API_KEY": ["GROQ_API_KEY", "VITE_GROQ_API_KEY"],
    "OPENAI_API_KEY": ["OPENAI_API_KEY", "VITE_OPENAI_API_KEY"],
    "GROK_API_KEY": ["GROK_API_KEY", "XAI_API_KEY", "VITE_GROK_API_KEY", "VITE_GROk_API_KEY", "GROk_API_KEY"],
    "XAI_API_KEY": ["XAI_API_KEY", "GROK_API_KEY", "VITE_GROK_API_KEY", "VITE_GROk_API_KEY"],
    "OPENROUTER_API_KEY": ["OPENROUTER_API_KEY", "VITE_OPENROUTER_API_KEY"],
    "ANTHROPIC_API_KEY": ["ANTHROPIC_API_KEY", "VITE_ANTHROPIC_API_KEY"],
    "GEMINI_API_KEY": ["GEMINI_API_KEY", "VITE_GEMINI_API_KEY", "GOOGLE_API_KEY", "VITE_GOOGLE_API_KEY"],
    "GOOGLE_API_KEY": ["GOOGLE_API_KEY", "GEMINI_API_KEY", "VITE_GEMINI_API_KEY"],
    "PERPLEXITY_API_KEY": ["PERPLEXITY_API_KEY", "VITE_PERPLEXITY_API_KEY"],
    "REPLICATE_API_KEY": ["REPLICATE_API_KEY", "VITE_REPLICATE_API_KEY"],
    "ELEVENLABS_API_KEY": ["ELEVENLABS_API_KEY", "VITE_ELEVENLABS_API_KEY"],
    "STABILITY_API_KEY": ["STABILITY_API_KEY", "VITE_STABILITY_AI_API_KEY", "STABILITY_AI_API_KEY"],
    "HF_TOKEN": ["HF_TOKEN", "HUGGINGFACE_API_KEY", "VITE_HUGGINGFACE_API_KEY", "HUGGING_FACE_HUB_TOKEN"],
    "LUMA_API_KEY": ["LUMA_API_KEY", "VITE_LUMA_API_KEY"],
    "DID_API_KEY": ["DID_API_KEY", "VITE_DID_API_KEY", "VITE_D-ID_API_KEY"],
    "OLLAMA_BASE_URL": ["OLLAMA_BASE_URL", "VITE_OLLAMA_URL"],
    "OLLAMA_MODEL": ["OLLAMA_MODEL", "VITE_OLLAMA_MODEL", "EREBUS_OLLAMA_MODEL"],
    "WORKER_URL": ["WORKER_URL", "VITE_WORKER_URL", "CLOUDFLARE_WORKER_URL"],
    "BROWSER_AGENT_URL": ["BROWSER_AGENT_URL", "EREBUS_BROWSER_URL"],
    "FAL_KEY": ["FAL_KEY", "FAL_API_KEY", "VITE_FAL_KEY"],
    "SUNO_API_KEY": ["SUNO_API_KEY", "VITE_SUNO_API_KEY"],
    "GROQ_MODEL": ["GROQ_MODEL", "VITE_GROQ_MODEL"],
}

_KEY_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_.-]*$")


def _parse_env_text(text: str) -> dict[str, str]:
    """Parse KEY=VALUE lines; skip banners, JSON fragments, bad keys."""
    out: dict[str, str] = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("═") or line.startswith("=") * 3:
            continue
        if line.startswith("{") or line.startswith("}") or line.startswith('"'):
            continue
        if "=" not in line:
            continue
        key, val = line.split("=", 1)
        key = key.strip()
        if not key or not _KEY_RE.match(key):
            continue
        val = val.strip()
        if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
            val = val[1:-1]
        # strip inline comments only when unquoted and obvious
        if " #" in val and not val.startswith("http"):
            val = val.split(" #", 1)[0].rstrip()
        if key not in out or val:
            out[key] = val
    return out


def _load_file(path: Path) -> dict[str, str]:
    try:
        if path.is_file():
            return _parse_env_text(path.read_text(encoding="utf-8", errors="replace"))
    except OSError as e:
        print(f"[env_loader] skip {path}: {e}")
    return {}


def load_erebus_env(force: bool = False) -> dict[str, str]:
    """Load env files into os.environ (no overwrite of already-set non-empty vars unless force)."""
    global _LOADED
    if _LOADED and not force:
        return snapshot_keys()

    merged: dict[str, str] = {}
    for path in (ROOT / ".env", LIFEOS_ROOT / ".env", HERMES_ENV):
        merged.update(_load_file(path))

    # Apply raw keys first
    for k, v in merged.items():
        if not v:
            continue
        if force or not os.environ.get(k):
            os.environ[k] = v

    # Apply aliases → canonical bare names
    for canonical, candidates in ALIASES.items():
        if os.environ.get(canonical) and not force:
            continue
        for c in candidates:
            # try exact, then case-insensitive scan of merged
            val = os.environ.get(c) or merged.get(c) or ""
            if not val:
                for mk, mv in merged.items():
                    if mk.upper() == c.upper() and mv:
                        val = mv
                        break
            if val:
                os.environ[canonical] = val
                break

    # Defaults
    os.environ.setdefault("OLLAMA_BASE_URL", "http://127.0.0.1:11434")
    os.environ.setdefault("BROWSER_AGENT_URL", "http://127.0.0.1:8100")
    os.environ.setdefault("EREBUS_FS_ROOT", str(LIFEOS_ROOT))
    os.environ.setdefault("EREBUS_SANDBOX_HOME", str(Path.home()))
    os.environ.setdefault("GROQ_MODEL", "llama-3.3-70b-versatile")
    os.environ.setdefault("OLLAMA_MODEL", "moondream:latest")

    _LOADED = True
    return snapshot_keys()


def get(key: str, default: str = "") -> str:
    load_erebus_env()
    if key in ALIASES or key in os.environ:
        # resolve alias
        if key in ALIASES:
            for c in ALIASES[key]:
                v = os.environ.get(c, "").strip()
                if v:
                    return v
        return os.environ.get(key, default).strip() or default
    return os.environ.get(key, default).strip() or default


def snapshot_keys() -> dict[str, bool]:
    """Presence map for health/capabilities (no secret values)."""
    load_erebus_env()
    return {k: bool(get(k)) for k in ALIASES.keys()}


def media_keys() -> dict[str, bool]:
    load_erebus_env()
    return {
        "replicate": bool(get("REPLICATE_API_KEY")),
        "elevenlabs": bool(get("ELEVENLABS_API_KEY")),
        "stability": bool(get("STABILITY_API_KEY")),
        "hf": bool(get("HF_TOKEN")),
        "luma": bool(get("LUMA_API_KEY")),
        "did": bool(get("DID_API_KEY")),
        "fal": bool(get("FAL_KEY")),
        "suno": bool(get("SUNO_API_KEY")),
    }
