from __future__ import annotations

import os
import httpx

from runtime.env_loader import load_erebus_env, get
from models import gpt as gpt_model
from models import grok as grok_model
from models import gemini as gemini_model
from models import perplexity as perplexity_model
from models import claude as claude_model


class ModelRouter:
    def __init__(self):
        load_erebus_env()
        self.groq_key = get("GROQ_API_KEY")
        self.grok_key = get("GROK_API_KEY") or get("XAI_API_KEY")
        self.openai_key = get("OPENAI_API_KEY")
        self.openrouter_key = get("OPENROUTER_API_KEY")
        self.gemini_key = get("GEMINI_API_KEY") or get("GOOGLE_API_KEY")
        self.perplexity_key = get("PERPLEXITY_API_KEY")
        self.anthropic_key = get("ANTHROPIC_API_KEY")
        self.ollama_url = get("OLLAMA_BASE_URL", "http://127.0.0.1:11434").rstrip("/")
        self.ollama_model = get("OLLAMA_MODEL", "moondream:latest")
        self.groq_model = get("GROQ_MODEL", "llama-3.3-70b-versatile")
        self.openrouter_model = os.getenv(
            "EREBUS_OPENROUTER_MODEL",
            "meta-llama/llama-3.3-70b-instruct:free",
        )
        self._ollama_ok: bool | None = None
        self._active = self._pick_active()

    def _pick_active(self) -> str:
        forced = os.getenv("EREBUS_MODEL", "").strip().lower()
        if forced in ("groq", "openrouter", "grok", "gemini", "openai", "ollama", "anthropic", "local"):
            return forced
        if self.groq_key:
            return "groq"
        if self.openrouter_key:
            return "openrouter"
        if self.grok_key:
            return "grok"
        if self.gemini_key:
            return "gemini"
        if self.openai_key:
            return "openai"
        return "ollama"  # try local; route() falls through to pattern-match if down

    def get_active_model(self) -> str:
        return self._active

    def available_models(self) -> list:
        available = []
        if self.groq_key:
            available.append(f"groq/{self.groq_model}")
        if self.openrouter_key:
            available.append(f"openrouter/{self.openrouter_model}")
        if self.grok_key:
            available.append("xai/grok-3-mini")
        if self.gemini_key:
            available.append("gemini/gemini-2.0-flash")
        if self.openai_key:
            available.append("openai/gpt-4o-mini")
        if self.anthropic_key:
            available.append("anthropic/claude-sonnet")
        if self.perplexity_key:
            available.append("perplexity/sonar")
        available.append(f"ollama/{self.ollama_model}")
        if not any(x for x in available if not x.startswith("ollama/")):
            available.append("local/pattern-match")
        return available

    def capabilities(self) -> dict:
        return {
            "active": self._active,
            "available": self.available_models(),
            "keys": {
                "groq": bool(self.groq_key),
                "openrouter": bool(self.openrouter_key),
                "grok": bool(self.grok_key),
                "gemini": bool(self.gemini_key),
                "openai": bool(self.openai_key),
                "anthropic": bool(self.anthropic_key),
                "perplexity": bool(self.perplexity_key),
                "ollama_url": self.ollama_url,
            },
        }

    async def route(self, message: str, mode: str, system: str, history: list) -> str:
        if mode == "search" and self.perplexity_key:
            try:
                return await self._call_perplexity(message, system, history)
            except Exception:
                pass

        order = [self._active] + [
            m for m in ("groq", "openrouter", "grok", "gemini", "openai", "ollama", "anthropic")
            if m != self._active
        ]
        last_err = None
        for name in order:
            try:
                if name == "groq" and self.groq_key:
                    return await self._call_groq(message, system, history)
                if name == "openrouter" and self.openrouter_key:
                    return await self._call_openrouter(message, system, history)
                if name == "grok" and self.grok_key:
                    return await self._call_grok(message, system, history)
                if name == "gemini" and self.gemini_key:
                    return await self._call_gemini(message, system, history)
                if name == "openai" and self.openai_key:
                    return await self._call_openai(message, system, history)
                if name == "anthropic" and self.anthropic_key:
                    return await self._call_anthropic(message, system, history)
                if name == "ollama":
                    out = await self._call_ollama(message, system, history)
                    if out is not None:
                        return out
            except Exception as e:
                last_err = e
                continue
        fb = self.local_fallback(message)
        if last_err:
            return f"{fb}\n\n[last model error: {last_err}]"
        return fb

    def _build_messages(self, system: str, history: list, message: str) -> list:
        msgs = []
        if system:
            msgs.append({"role": "system", "content": system[:8000]})
        for h in history[-12:]:
            role = h.get("role", "user")
            content = h.get("content", "")
            if role in ("user", "assistant") and content:
                msgs.append({"role": role, "content": content})
        msgs.append({"role": "user", "content": message})
        return msgs

    async def _call_groq(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        return await gpt_model.chat(
            self.groq_key, msgs, model=self.groq_model,
            base_url="https://api.groq.com/openai/v1",
        )

    async def _call_openrouter(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        async with httpx.AsyncClient(timeout=60) as client:
            r = await client.post(
                "https://openrouter.ai/api/v1/chat/completions",
                headers={
                    "Authorization": f"Bearer {self.openrouter_key}",
                    "Content-Type": "application/json",
                    "HTTP-Referer": "https://lifeos1.local",
                    "X-Title": "Erebus",
                },
                json={"model": self.openrouter_model, "messages": msgs, "max_tokens": 2000},
            )
            r.raise_for_status()
            return r.json()["choices"][0]["message"]["content"]

    async def _call_grok(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        return await grok_model.chat(self.grok_key, msgs)

    async def _call_openai(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        return await gpt_model.chat(self.openai_key, msgs)

    async def _call_gemini(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        return await gemini_model.chat(self.gemini_key, msgs)

    async def _call_perplexity(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        return await perplexity_model.chat(self.perplexity_key, msgs)

    async def _call_anthropic(self, message: str, system: str, history: list) -> str:
        msgs = self._build_messages(system, history, message)
        return await claude_model.chat(self.anthropic_key, msgs)

    async def _call_ollama(self, message: str, system: str, history: list) -> str | None:
        try:
            msgs = self._build_messages(system, history, message)
            async with httpx.AsyncClient(timeout=90) as client:
                # quick tags check once
                if self._ollama_ok is None:
                    try:
                        t = await client.get(f"{self.ollama_url}/api/tags")
                        self._ollama_ok = t.status_code == 200
                    except Exception:
                        self._ollama_ok = False
                if not self._ollama_ok:
                    return None
                r = await client.post(
                    f"{self.ollama_url}/v1/chat/completions",
                    json={"model": self.ollama_model, "messages": msgs, "max_tokens": 1500},
                )
                if r.status_code >= 400:
                    # native chat
                    r = await client.post(
                        f"{self.ollama_url}/api/chat",
                        json={"model": self.ollama_model, "messages": msgs, "stream": False},
                    )
                    r.raise_for_status()
                    return r.json().get("message", {}).get("content", "")
                r.raise_for_status()
                return r.json()["choices"][0]["message"]["content"]
        except Exception:
            self._ollama_ok = False
            return None

    def local_fallback(self, message: str) -> str:
        t = message.lower()
        if any(x in t for x in ["family", "dinner", "jamal", "elena"]):
            return (
                "Family protection protocols active. Dinner at 6:30pm is non-negotiable. "
                "Jamal soccer 4pm, Elena dance — both locked."
            )
        if any(x in t for x in ["lead", "crm", "follow", "sarah", "gino"]):
            return "CRM context loaded. Ready to draft outreach or log follow-up. Which lead should I prioritize?"
        if any(x in t for x in ["status", "health", "online", "capabilit"]):
            return (
                f"Erebus core online. Active brain: {self._active}. "
                f"Available: {', '.join(self.available_models())}."
            )
        if any(x in t for x in ["file", "list", "ls ", "read "]):
            return "File tools ready: FS_LS, FS_READ, FS_WRITE, FS_DELETE, LIST_DIR, READ_FILE, WRITE_FILE."
        return (
            f'Erebus received: "{message[:120]}"\n\n'
            "Local pattern core answered (cloud/local LLM unavailable or failed). "
            "Keys load from advanced_agent/.env, LifeOS .env, and Hermes .env via aliases."
        )
