# Web search utilities
# ============================================================
from __future__ import annotations

import re
import httpx

from runtime.env_loader import get


async def search_web(query: str, limit: int = 5) -> str:
    query = (query or "").strip()
    if not query:
        return "[SEARCH] empty query"

    worker = get("WORKER_URL").rstrip("/")
    if worker:
        try:
            async with httpx.AsyncClient(timeout=20) as client:
                r = await client.post(
                    f"{worker}/api/browse/search",
                    json={"query": query},
                )
                if r.is_success:
                    data = r.json()
                    results = data.get("results") or data.get("items") or []
                    if results:
                        lines = []
                        for i, item in enumerate(results[:limit], 1):
                            if isinstance(item, dict):
                                title = item.get("title") or item.get("name") or ""
                                url = item.get("url") or item.get("href") or ""
                                snip = item.get("snippet") or item.get("text") or ""
                                lines.append(f"{i}. {title} — {url}\n   {snip[:200]}")
                            else:
                                lines.append(f"{i}. {item}")
                        return f"[SEARCH: {query}]\n" + "\n".join(lines)
        except Exception:
            pass

    # DuckDuckGo instant
    try:
        async with httpx.AsyncClient(timeout=12) as client:
            r = await client.get(
                "https://api.duckduckgo.com/",
                params={"q": query, "format": "json", "no_html": 1, "skip_disambig": 1},
                headers={"User-Agent": "Mozilla/5.0 Erebus/3"},
            )
            data = r.json()
        abstract = data.get("AbstractText", "") or ""
        related = []
        for t in data.get("RelatedTopics", [])[:limit]:
            if isinstance(t, dict) and t.get("Text"):
                related.append(t["Text"])
            elif isinstance(t, dict) and "Topics" in t:
                for st in t["Topics"][:2]:
                    if isinstance(st, dict) and st.get("Text"):
                        related.append(st["Text"])
        result = abstract or " | ".join(related) or "No instant results."
        return f"[SEARCH: {query}] {result[:1200]}"
    except Exception as e:
        return f"[SEARCH error] {e}"


async def fetch_url(url: str, max_chars: int = 4000) -> str:
    url = (url or "").strip()
    if not url:
        return "[BROWSE] empty url"
    worker = get("WORKER_URL").rstrip("/")
    if worker:
        try:
            async with httpx.AsyncClient(timeout=25) as client:
                r = await client.post(
                    f"{worker}/api/browse/fetch",
                    json={"url": url, "extract": "text"},
                )
                if r.is_success:
                    data = r.json()
                    text = data.get("text") or data.get("content") or ""
                    if text:
                        return f"[BROWSE: {url}] {(data.get('title') or '')}\n{text[:max_chars]}"
        except Exception:
            pass
    try:
        async with httpx.AsyncClient(timeout=20, follow_redirects=True) as client:
            r = await client.get(url, headers={"User-Agent": "Mozilla/5.0 Erebus/3"})
            r.raise_for_status()
            text = re.sub(r"(?is)<script.*?>.*?</script>", " ", r.text)
            text = re.sub(r"(?is)<style.*?>.*?</style>", " ", text)
            text = re.sub(r"<[^>]+>", " ", text)
            text = re.sub(r"\s+", " ", text).strip()
            return f"[BROWSE: {url}] {text[:max_chars]}"
    except Exception as e:
        return f"[BROWSE error] {e}"
