# Safe local code / shell execution for Erebus
# ============================================================
from __future__ import annotations

import os
import subprocess
import tempfile
from pathlib import Path

from runtime.env_loader import get, LIFEOS_ROOT


ALLOWED_ROOTS = []


def _roots() -> list[Path]:
    global ALLOWED_ROOTS
    if ALLOWED_ROOTS:
        return ALLOWED_ROOTS
    roots = [
        Path(get("EREBUS_FS_ROOT", str(LIFEOS_ROOT))).resolve(),
        Path(get("EREBUS_SANDBOX_HOME", str(Path.home()))).resolve(),
        (LIFEOS_ROOT / "advanced_agent").resolve(),
    ]
    ALLOWED_ROOTS = roots
    return roots


def path_allowed(path: str | Path) -> bool:
    try:
        p = Path(path).expanduser().resolve()
    except Exception:
        return False
    for root in _roots():
        try:
            p.relative_to(root)
            return True
        except ValueError:
            continue
    return False


def run_command(cmd: str, timeout: int = 30, cwd: str | None = None) -> str:
    if not cmd or not str(cmd).strip():
        return "[CMD] empty"
    work = cwd or str(LIFEOS_ROOT)
    if not path_allowed(work):
        work = str(LIFEOS_ROOT)
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=work,
            env={**os.environ, "PYTHONPATH": ""},
        )
        out = (result.stdout or "") + (("\n" + result.stderr) if result.stderr else "")
        return out.strip() or f"(exit {result.returncode}, no output)"
    except subprocess.TimeoutExpired:
        return f"[CMD timeout after {timeout}s]"
    except Exception as e:
        return f"[CMD error] {e}"


def run_python(code: str, timeout: int = 30) -> str:
    """Run a short Python snippet in a temp file under sandbox."""
    sandbox = (LIFEOS_ROOT / "advanced_agent" / "sandbox").resolve()
    sandbox.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile("w", suffix=".py", dir=sandbox, delete=False, encoding="utf-8") as f:
        f.write(code)
        path = f.name
    try:
        return run_command(f'"{os.sys.executable}" "{path}"', timeout=timeout, cwd=str(sandbox))
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass
