# Virtual + real filesystem for Erebus
# ============================================================
from __future__ import annotations

import json
import os
from pathlib import Path

from runtime.env_loader import get, LIFEOS_ROOT, ROOT
from utils.code_executor import path_allowed

VFS_FILE = ROOT / "erebus_vfs.json"


def _initial_vfs() -> dict:
    return {
        "/": {
            "lifeos": {
                "notes": {
                    "family-goals.txt": "Protect dinner times. Jamal soccer 4pm. Elena dance.",
                    "business-leads.txt": "Sarah Patel - Decatur event plumbing - Warm lead",
                },
                "media": {},
                "reports": {
                    "life-pulse.md": "# Life Pulse\nHarmony Score: 89\nFamily protected",
                },
                "lists": {},
                "skills": {},
            },
            "config": {
                "agent-settings.json": json.dumps({"voice": "controlled", "priority": "family-first"}),
            },
        }
    }


class VirtualFS:
    def __init__(self, path: Path = VFS_FILE):
        self.path = path
        self.fs = self._load()

    def _load(self) -> dict:
        try:
            if self.path.exists():
                return json.loads(self.path.read_text(encoding="utf-8"))
        except Exception:
            pass
        return _initial_vfs()

    def save(self):
        self.path.write_text(json.dumps(self.fs, indent=2, ensure_ascii=False), encoding="utf-8")

    def _walk(self, path: str, create: bool = False):
        parts = [p for p in path.replace("\\", "/").split("/") if p]
        cur = self.fs.setdefault("/", {})
        for part in parts[:-1]:
            if part not in cur:
                if not create:
                    return None, None
                cur[part] = {}
            if not isinstance(cur[part], dict):
                return None, None
            cur = cur[part]
        return cur, (parts[-1] if parts else None)

    def ls(self, path: str = "/") -> str:
        path = path or "/"
        if path in ("/", ""):
            node = self.fs.get("/", {})
            return "\n".join(sorted(node.keys())) or "(empty)"
        cur, name = self._walk(path if path.endswith("/x") else path + "/.")  # force dir walk
        # simpler: navigate full path as directory
        parts = [p for p in path.replace("\\", "/").split("/") if p]
        node = self.fs.get("/", {})
        for part in parts:
            if not isinstance(node, dict) or part not in node:
                return f"Error: Path not found: {path}"
            node = node[part]
        if not isinstance(node, dict):
            return f"(file) {path}"
        return "\n".join(sorted(node.keys())) or "(empty)"

    def read(self, path: str) -> str:
        parts = [p for p in path.replace("\\", "/").split("/") if p]
        if not parts:
            return "Error: no path"
        node = self.fs.get("/", {})
        for part in parts[:-1]:
            if not isinstance(node, dict) or part not in node:
                return f"Error: File not found: {path}"
            node = node[part]
        if not isinstance(node, dict) or parts[-1] not in node:
            return f"Error: File not found: {path}"
        val = node[parts[-1]]
        if isinstance(val, dict):
            return f"Error: {path} is a directory"
        return str(val)

    def write(self, path: str, content: str) -> str:
        parts = [p for p in path.replace("\\", "/").split("/") if p]
        if not parts:
            return "Error: no path"
        node = self.fs.setdefault("/", {})
        for part in parts[:-1]:
            if part not in node or not isinstance(node[part], dict):
                node[part] = {}
            node = node[part]
        node[parts[-1]] = content
        self.save()
        return f"✓ Wrote VFS {path} ({len(content)} chars)"

    def delete(self, path: str) -> str:
        parts = [p for p in path.replace("\\", "/").split("/") if p]
        if not parts:
            return "Error: no path"
        node = self.fs.get("/", {})
        for part in parts[:-1]:
            if not isinstance(node, dict) or part not in node:
                return "Error: Path not found"
            node = node[part]
        if isinstance(node, dict) and parts[-1] in node:
            del node[parts[-1]]
            self.save()
            return f"✓ Deleted VFS {path}"
        return "Error: File not found"


_vfs = VirtualFS()


def vfs() -> VirtualFS:
    return _vfs


def real_list_dir(path: str = "") -> str:
    p = Path(path or get("EREBUS_FS_ROOT", str(LIFEOS_ROOT))).expanduser()
    if not path_allowed(p):
        return f"Error: path not allowed: {p}"
    if not p.exists():
        return f"Error: not found: {p}"
    if p.is_file():
        return f"(file) {p}"
    try:
        names = sorted(os.listdir(p))[:500]
        return "\n".join(names) or "(empty)"
    except Exception as e:
        return f"Error: {e}"


def real_read(path: str, max_chars: int = 100_000) -> str:
    p = Path(path).expanduser()
    if not path_allowed(p):
        return f"Error: path not allowed: {p}"
    if not p.is_file():
        return f"Error: not a file: {p}"
    try:
        data = p.read_text(encoding="utf-8", errors="replace")
        if len(data) > max_chars:
            return data[:max_chars] + f"\n… truncated {len(data)-max_chars} chars"
        return data
    except Exception as e:
        return f"Error: {e}"


def real_write(path: str, content: str) -> str:
    p = Path(path).expanduser()
    if not path_allowed(p):
        return f"Error: path not allowed: {p}"
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content or "", encoding="utf-8")
        return f"✓ Wrote {p} ({len(content or '')} chars)"
    except Exception as e:
        return f"Error: {e}"


def real_delete(path: str) -> str:
    p = Path(path).expanduser()
    if not path_allowed(p):
        return f"Error: path not allowed: {p}"
    try:
        if p.is_file():
            p.unlink()
            return f"✓ Deleted {p}"
        return f"Error: not a file: {p}"
    except Exception as e:
        return f"Error: {e}"
