# Browser tools — prefer local browser agent :8100, then worker, then httpx
# ============================================================
from __future__ import annotations

import httpx

from runtime.env_loader import get
from utils.web_search import search_web, fetch_url


def browser_base() -> str:
    return get("BROWSER_AGENT_URL", "http://127.0.0.1:8100").rstrip("/")


async def _post_browser(path: str, body: dict, timeout: float = 30.0) -> dict | None:
    url = f"{browser_base()}{path}"
    try:
        async with httpx.AsyncClient(timeout=timeout) as client:
            r = await client.post(url, json=body)
            if r.is_success:
                return r.json()
    except Exception:
        return None
    return None


async def browse_url(url: str) -> str:
    data = await _post_browser("/browse/navigate", {"url": url, "sessionId": "erebus"}, timeout=35)
    if data:
        text = data.get("text") or data.get("content") or ""
        title = data.get("title") or ""
        return f"[BROWSE: {data.get('url') or url}] {title}\n{str(text)[:2000]}"
    return await fetch_url(url)


async def search(query: str) -> str:
    data = await _post_browser("/browse/search", {"query": query, "engine": "ddg"}, timeout=25)
    if data and (data.get("results") is not None):
        results = data.get("results") or []
        lines = []
        for i, item in enumerate(results[:8], 1):
            if isinstance(item, dict):
                lines.append(f"{i}. {item.get('title','')} — {item.get('url','')}\n   {str(item.get('snippet',''))[:180]}")
            else:
                lines.append(f"{i}. {item}")
        return f"[SEARCH: {query}]\n" + ("\n".join(lines) or "No results")
    return await search_web(query)


async def scrape(url: str, selector: str | None = None) -> str:
    body = {"sessionId": "erebus", "selector": selector, "extractType": "text", "url": url}
    data = await _post_browser("/browse/extract", body, timeout=30)
    if data:
        return f"[SCRAPE: {url}] {data.get('title','')}\n{str(data.get('text',''))[:2000]}"
    return await fetch_url(url)


async def click(selector: str | None = None, text: str | None = None) -> str:
    data = await _post_browser(
        "/browse/click",
        {"selector": selector, "text": text, "sessionId": "erebus"},
        timeout=20,
    )
    if data:
        return f"[CLICK] {data.get('text') or 'ok'} @ {data.get('url','')}"
    return "[CLICK] Browser agent offline (start archive/browser_agent on :8100)"


async def fill_form(fields: list, submit: bool = False) -> str:
    data = await _post_browser(
        "/browse/fill",
        {"fields": fields, "submit": submit, "sessionId": "erebus"},
        timeout=25,
    )
    if data:
        return f"[FILL] {data.get('text') or 'ok'}"
    return "[FILL] Browser agent offline"


async def screenshot() -> str:
    data = await _post_browser("/browse/screenshot", {"sessionId": "erebus"}, timeout=20)
    if data:
        shot = data.get("screenshot") or data.get("path") or data.get("url") or "captured"
        return f"[SCREENSHOT] {str(shot)[:500]}"
    return "[SCREENSHOT] Browser agent offline"


async def status() -> dict:
    try:
        async with httpx.AsyncClient(timeout=3) as client:
            r = await client.get(f"{browser_base()}/")
