# Media generation — image / video / speech / music
# Uses Stability, Replicate, ElevenLabs, HF, Luma, Pollinations fallback
# ============================================================
from __future__ import annotations

import asyncio
import base64
import time
from pathlib import Path

import httpx

from runtime.env_loader import get, ROOT, media_keys

OUT_DIR = ROOT / "outputs"
OUT_DIR.mkdir(parents=True, exist_ok=True)


def _save_bytes(data: bytes, suffix: str) -> str:
    name = f"erebus_{int(time.time()*1000)}{suffix}"
    path = OUT_DIR / name
    path.write_bytes(data)
    return str(path)


async def _replicate_run(owner: str, name: str, input_data: dict, max_ms: int = 180000) -> object:
    key = get("REPLICATE_API_KEY")
    if not key:
        raise RuntimeError("REPLICATE_API_KEY not set")
    headers = {"Authorization": f"Token {key}", "Content-Type": "application/json", "Prefer": "wait"}
    async with httpx.AsyncClient(timeout=120) as client:
        r = await client.post(
            f"https://api.replicate.com/v1/models/{owner}/{name}/predictions",
            headers=headers,
            json={"input": input_data},
        )
        r.raise_for_status()
        pred = r.json()
        if pred.get("status") == "succeeded":
            return pred.get("output")
        if pred.get("status") == "failed":
            raise RuntimeError(pred.get("error") or "replicate failed")
        get_url = (pred.get("urls") or {}).get("get")
        if not get_url:
            return pred.get("output")
        deadline = time.time() + max_ms / 1000
        while time.time() < deadline:
            await asyncio.sleep(3)
            pr = await client.get(get_url, headers={"Authorization": f"Token {key}"})
            pr.raise_for_status()
            d = pr.json()
            if d.get("status") == "succeeded":
                return d.get("output")
            if d.get("status") == "failed":
                raise RuntimeError(d.get("error") or "replicate failed")
        raise TimeoutError("replicate poll timeout")


async def generate_image(prompt: str, width: int = 1024, height: int = 1024) -> dict:
    prompt = (prompt or "").strip()
    if not prompt:
        return {"error": "empty prompt"}

    stab = get("STABILITY_API_KEY")
    if stab:
        try:
            ar = "1:1" if width == height else ("16:9" if width > height else "9:16")
            async with httpx.AsyncClient(timeout=90) as client:
                r = await client.post(
                    "https://api.stability.ai/v2beta/stable-image/generate/core",
                    headers={"Authorization": f"Bearer {stab}", "Accept": "image/*"},
                    files={"none": (None, "")},
                    data={"prompt": prompt, "output_format": "webp", "aspect_ratio": ar},
                )
                if r.is_success and r.headers.get("content-type", "").startswith("image"):
                    path = _save_bytes(r.content, ".webp")
                    return {"url": path, "source": "Stability AI", "prompt": prompt}
        except Exception as e:
            last = str(e)

    if get("REPLICATE_API_KEY"):
        try:
            out = await _replicate_run("black-forest-labs", "flux-schnell", {"prompt": prompt, "num_outputs": 1})
            url = out[0] if isinstance(out, list) else out
            if url:
                return {"url": str(url), "source": "FLUX Schnell (Replicate)", "prompt": prompt}
        except Exception as e:
            last = str(e)

    hf = get("HF_TOKEN")
    if hf:
        try:
            async with httpx.AsyncClient(timeout=90) as client:
                r = await client.post(
                    "https://api-inference.huggingface.co/models/black-forest-labs/FLUX.1-schnell",
                    headers={"Authorization": f"Bearer {hf}"},
                    json={"inputs": prompt},
                )
                if r.is_success and "image" in r.headers.get("content-type", ""):
                    path = _save_bytes(r.content, ".png")
                    return {"url": path, "source": "HuggingFace FLUX", "prompt": prompt}
        except Exception as e:
            last = str(e)

    # Always-on free fallback
    from urllib.parse import quote
    pol = (
        f"https://image.pollinations.ai/prompt/{quote(prompt)}"
        f"?width={width}&height={height}&model=flux&nologo=true"
    )
    return {"url": pol, "source": "Pollinations.ai (free)", "prompt": prompt}


async def edit_image(image_url: str, description: str) -> dict:
    # Stability edit if possible; else regenerate from description
    return await generate_image(f"{description} (based on {image_url})")


async def generate_music(prompt: str, duration: int = 30) -> dict:
    prompt = (prompt or "").strip()
    if get("REPLICATE_API_KEY"):
        try:
            out = await _replicate_run(
                "meta",
                "musicgen",
                {
                    "prompt": prompt,
                    "duration": min(int(duration or 30), 60),
                    "model_version": "large",
                    "output_format": "mp3",
                },
                max_ms=300000,
            )
            url = out if isinstance(out, str) else (out[0] if isinstance(out, list) else None)
            if url:
                return {"url": str(url), "source": "MusicGen (Replicate)", "prompt": prompt}
        except Exception as e:
            err = str(e)
    else:
        err = "REPLICATE_API_KEY missing"
    return {"error": f"Music gen unavailable: {err}"}


async def generate_speech(text: str, voice_key: str = "default") -> dict:
    text = (text or "").strip()
    if not text:
        return {"error": "empty text"}
    voices = {
        "default": "21m00Tcm4TlvDq8ikWAM",
        "male": "IKne3meq5aSn9XLyUdCD",
        "british": "N2lVS1w4EtoT3dr4eOWO",
    }
    voice_id = voices.get(voice_key, voices["default"])
    key = get("ELEVENLABS_API_KEY")
    if key:
        try:
            async with httpx.AsyncClient(timeout=60) as client:
                r = await client.post(
                    f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                    headers={
                        "xi-api-key": key,
                        "Content-Type": "application/json",
                        "Accept": "audio/mpeg",
                    },
                    json={"text": text, "model_id": "eleven_monolingual_v1"},
                )
                if r.is_success:
                    path = _save_bytes(r.content, ".mp3")
                    return {"url": path, "source": "ElevenLabs", "text": text[:120]}
                return {"error": f"ElevenLabs {r.status_code}: {r.text[:200]}"}
        except Exception as e:
            return {"error": str(e)}
    return {"error": "ELEVENLABS_API_KEY not set"}


async def generate_video(prompt: str, aspect: str = "16:9") -> dict:
    prompt = (prompt or "").strip()
    luma = get("LUMA_API_KEY")
    if luma:
        try:
            async with httpx.AsyncClient(timeout=60) as client:
                r = await client.post(
                    "https://api.lumalabs.ai/dream-machine/v1/generations",
                    headers={"Authorization": f"Bearer {luma}", "Content-Type": "application/json"},
                    json={"prompt": prompt, "aspect_ratio": aspect},
                )
                if r.is_success:
                    data = r.json()
                    return {"id": data.get("id"), "status": data.get("state") or data.get("status"), "source": "Luma", "raw": data}
                return {"error": f"Luma {r.status_code}: {r.text[:200]}"}
        except Exception as e:
            return {"error": str(e)}

    if get("REPLICATE_API_KEY"):
        try:
            # best-effort generic video model id may change; return clear error if fails
            out = await _replicate_run(
                "anotherjesse",
                "zeroscope-v2-xl",
                {"prompt": prompt},
                max_ms=300000,
            )
            url = out if isinstance(out, str) else (out[0] if isinstance(out, list) else str(out))
            return {"url": str(url), "source": "Replicate video", "prompt": prompt}
        except Exception as e:
            return {"error": f"Video gen failed: {e}"}
    return {"error": "No LUMA_API_KEY or REPLICATE_API_KEY for video"}


async def image_to_video(image_url: str, motion: str = "smooth cinematic motion") -> dict:
    return await generate_video(f"{motion}. Image reference: {image_url}")


async def generate_avatar(script: str, voice_id: str = "en-US-JennyNeural") -> dict:
    # Prefer speech + note; D-ID if key present
    did = get("DID_API_KEY")
    speech = await generate_speech(script)
    if did:
        try:
            token = base64.b64encode(f"{did}:".encode()).decode()
