                        "source_url": "https://create-images-results.d-id.com/default_presenter.jpg",
                    },
                )
                if r.is_success:
                    return {"source": "D-ID", "data": r.json(), "speech": speech}
                return {"error": f"D-ID {r.status_code}", "speech": speech}
        except Exception as e:
            return {"error": str(e), "speech": speech}
    return {"source": "speech-only", "speech": speech, "note": "DID_API_KEY not set — returned TTS only"}


