from __future__ import annotations

import json
import re
import time
from pathlib import Path

from runtime.env_loader import ROOT

SKILLS_FILE = ROOT / "erebus_skills.json"


def _load() -> dict:
    try:
        if SKILLS_FILE.exists():
            return json.loads(SKILLS_FILE.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {"skills": {}}


def _save(data: dict):
    SKILLS_FILE.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")


def list_skills() -> str:
    data = _load()
    skills = data.get("skills") or {}
    if not skills:
        return "[SKILLS] none yet — use SAVE_SKILL: name=X body=Y"
    lines = []
    for name, meta in sorted(skills.items()):
        body = (meta.get("body") or "")[:80].replace("\n", " ")
        lines.append(f"- {name}: {body}")
    return "[SKILLS]\n" + "\n".join(lines)


def get_skill(name: str) -> str:
    skills = (_load().get("skills") or {})
    meta = skills.get(name.strip())
    if not meta:
        return f"[SKILL] not found: {name}"
    return f"[SKILL {name}]\n{meta.get('body','')}"


def save_skill(name: str, body: str) -> str:
    name = (name or "").strip()
    body = (body or "").strip()
    if not name or not body:
        return "[SKILL] need name and body"
    data = _load()
    data.setdefault("skills", {})[name] = {
        "body": body,
        "updated": time.time(),
    }
    _save(data)
    return f"[SKILL] saved: {name} ({len(body)} chars)"


def delete_skill(name: str) -> str:
    data = _load()
    skills = data.setdefault("skills", {})
    if name in skills:
        del skills[name]
        _save(data)
        return f"[SKILL] deleted: {name}"
    return f"[SKILL] not found: {name}"


def parse_save_spec(spec: str) -> tuple[str, str]:
    # name=X body=Y
    m_name = re.search(r"name=([^\s=]+(?:\s(?!\w+=)[^\s=]+)*)", spec, re.I)
    m_body = re.search(r"body=(.+)$", spec, re.I | re.S)
    return (m_name.group(1).strip() if m_name else "", m_body.group(1).strip() if m_body else "")
