from __future__ import annotations

import json
import re
import time
from pathlib import Path

from runtime.env_loader import ROOT

LISTS_FILE = ROOT / "erebus_lists.json"


def _load() -> dict:
    try:
        if LISTS_FILE.exists():
            return json.loads(LISTS_FILE.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {"lists": {}}


def _save(data: dict):
    LISTS_FILE.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")


def list_all() -> str:
    lists = (_load().get("lists") or {})
    if not lists:
        return "[LISTS] none — CREATE_LIST: name=X items=a;b;c"
    lines = []
    for name, meta in sorted(lists.items()):
        items = meta.get("items") or []
        lines.append(f"- {name} ({len(items)} items)")
    return "[LISTS]\n" + "\n".join(lines)


def get_list(name: str) -> str:
    meta = (_load().get("lists") or {}).get(name.strip())
    if not meta:
        return f"[LIST] not found: {name}"
    items = meta.get("items") or []
    body = "\n".join(f"{i+1}. {it}" for i, it in enumerate(items))
    return f"[LIST {name}]\n{body or '(empty)'}"


def create_list(name: str, items: list[str] | None = None) -> str:
    name = (name or "").strip()
    if not name:
        return "[LIST] name required"
    data = _load()
    data.setdefault("lists", {})[name] = {
        "items": list(items or []),
        "updated": time.time(),
    }
    _save(data)
    return f"[LIST] created: {name} ({len(items or [])} items)"


def add_items(name: str, items: list[str]) -> str:
    data = _load()
    lists = data.setdefault("lists", {})
    if name not in lists:
        lists[name] = {"items": [], "updated": time.time()}
    lists[name]["items"].extend(items)
    lists[name]["updated"] = time.time()
    _save(data)
    return f"[LIST] {name}: now {len(lists[name]['items'])} items"


def remove_item(name: str, index: int) -> str:
    data = _load()
    lists = data.get("lists") or {}
    if name not in lists:
        return f"[LIST] not found: {name}"
    items = lists[name].get("items") or []
    if index < 1 or index > len(items):
        return f"[LIST] bad index {index}"
    removed = items.pop(index - 1)
    lists[name]["items"] = items
    _save(data)
    return f"[LIST] removed from {name}: {removed}"


def parse_items(raw: str) -> list[str]:
    raw = (raw or "").strip()
    if not raw:
        return []
    if ";" in raw:
        return [x.strip() for x in raw.split(";") if x.strip()]
    if "\n" in raw:
        return [x.strip() for x in raw.splitlines() if x.strip()]
    return [x.strip() for x in raw.split(",") if x.strip()]


def parse_create_spec(spec: str) -> tuple[str, list[str]]:
    m_name = re.search(r"name=([^\s=]+(?:\s(?!\w+=)[^\s=]+)*)", spec, re.I)
    m_items = re.search(r"items=(.+)$", spec, re.I | re.S)
    name = m_name.group(1).strip() if m_name else ""
    items = parse_items(m_items.group(1) if m_items else "")
    return name, items
