{"content":"# ============================================================
# Erebus Planner — Multi-step agentic loop with full tool surface
# ============================================================

from __future__ import annotations

import json
import re
import webbrowser
from typing import AsyncGenerator

from .memory import ErebusMemory
from .router import ModelRouter
from .tools import browser, files, lists, media, skills
from utils.code_executor import run_command, run_python
from utils.web_search import search_web, fetch_url

MAX_STEPS = 10

PLANNER_SYSTEM = """You are Erebus — autonomous intelligence for Chris Green / LifeOS1.
You execute multi-step tasks by reasoning and using tools.

TOOL SYNTAX (one tool line per response when using a tool; final answer with DONE):
  SEARCH_WEB: query
  BROWSE_URL: https://url
  SCRAPE_PAGE: https://url | selector=.css
  CLICK: selector=... OR text=...
  FILL_FORM: selector=#id value=text
  SCREENSHOT:
  OPEN_BROWSER: https://url
  FS_LS: /path
  FS_READ: /path
  FS_WRITE: /path | content
  FS_DELETE: /path
  LIST_DIR: C:\\path
  READ_FILE: C:\\path
  WRITE_FILE: C:\\path | content
  RUN_CMD: command
  RUN_PYTHON: code
  GEN_IMAGE: prompt
  GEN_VIDEO: prompt
  GEN_MUSIC: prompt
  GEN_SPEECH: text
  GEN_AVATAR: script
  LIST_SKILLS:
  GET_SKILL: name
  SAVE_SKILL: name=X body=Y
  LIST_LISTS:
  GET_LIST: name
  CREATE_LIST: name=X items=a;b;c
  ADD_LIST: name=X items=a;b
  READ_LIFEOS: crm | tasks | goals | calendar | contacts
  UPDATE_LEAD: name=X status=hot notes=Y
  CREATE_TASK: text=X priority=high|medium|low
  REMEMBER_FACT: key=X value=Y
  DRAFT_EMAIL: to=X subject=Y body=Z
  NOTIFY: message=X
  DONE: final answer here

RULES:
- Think step by step. Use tools for real data before concluding.
- Emit ONE tool call OR DONE per response (short thought OK above the tool line).
- Never fabricate CRM/file/media results — call tools.
- Protect family time (dinner 6:30, Jamal soccer Tue 4pm).
- Keep steps tight unless depth is required.
"""


def _kv(spec: str) -> dict:
    return dict(re.findall(r"(\w+)=([^=\n]+?)(?=\s+\w+=|$)", spec.strip()))


class ToolExecutor:
    def __init__(self, lifeos_data: dict | None = None, memory: ErebusMemory | None = None):
        self.lifeos_data = lifeos_data or {}
        self.memory = memory
        self.pending_side_effects: list[dict] = []

    def set_memory(self, memory: ErebusMemory):
        self.memory = memory

    async def execute(self, line: str) -> str:
        line = line.strip()
        try:
            if line.startswith("SEARCH_WEB:"):
                return await browser.search(line[11:].strip())
            if line.startswith("BROWSE_URL:"):
                return await browser.browse_url(line[11:].strip())
            if line.startswith("SCRAPE_PAGE:"):
                spec = line[12:].strip()
                parts = [p.strip() for p in spec.split("|", 1)]
                url = parts[0]
                sel = None
                if len(parts) > 1 and parts[1].startswith("selector="):
                    sel = parts[1][9:].strip()
                return await browser.scrape(url, sel)
            if line.startswith("CLICK:"):
                p = _kv(line[6:])
                return await browser.click(selector=p.get("selector"), text=p.get("text"))
            if line.startswith("FILL_FORM:"):
                p = _kv(line[10:])
                fields = [{"selector": p.get("selector", ""), "value": p.get("value", "")}]
                return await browser.fill_form(fields, submit=p.get("submit", "").lower() in ("1", "true", "yes"))
            if line.startswith("SCREENSHOT:"):
                return await browser.screenshot()
            if line.startswith("OPEN_BROWSER:"):
                url = line[13:].strip()
                webbrowser.open(url)
                return f"[OPEN_BROWSER] {url}"

            if line.startswith("FS_LS:"):
                return f"[FS_LS]\n{files.vfs().ls(line[6:].strip() or '/')}"
            if line.startswith("FS_READ:"):
                return f"[FS_READ]\n{files.vfs().read(line[8:].strip())}"
            if line.startswith("FS_WRITE:"):
                body = line[9:].strip()
                if "|" in body:
                    path, content = body.split("|", 1)
                else:
                    path, content = body, ""
                return files.vfs().write(path.strip(), content.strip())
            if line.startswith("FS_DELETE:"):
                return files.vfs().delete(line[10:].strip())

            if line.startswith("LIST_DIR:"):
                return f"[LIST_DIR]\n{files.real_list_dir(line[9:].strip())}"
            if line.startswith("READ_FILE:"):
                return f"[READ_FILE]\n{files.real_read(line[10:].strip())}"
            if line.startswith("WRITE_FILE:"):
                body = line[11:].strip()
                if "|" in body:
                    path, content = body.split("|", 1)
                else:
                    path, content = body, ""
                return files.real_write(path.strip(), content)
            if line.startswith("DELETE_FILE:"):
                return files.real_delete(line[12:].strip())

            if line.startswith("RUN_CMD:"):
                return f"[RUN_CMD]\n{run_command(line[8:].strip())}"
            if line.startswith("RUN_PYTHON:"):
                return f"[RUN_PYTHON]\n{run_python(line[11:].strip())}"

            if line.startswith("GEN_IMAGE:"):
                r = await media.generate_image(line[10:].strip())
                return f"[GEN_IMAGE] {json.dumps(r)[:800]}"
            if line.startswith("GEN_VIDEO:"):
                r = await media.generate_video(line[10:].strip())
                return f"[GEN_VIDEO] {json.dumps(r)[:800]}"
            if line.startswith("GEN_MUSIC:"):
                r = await media.generate_music(line[10:].strip())
                return f"[GEN_MUSIC] {json.dumps(r)[:800]}"
            if line.startswith("GEN_SPEECH:"):
                r = await media.generate_speech(line[11:].strip())
                return f"[GEN_SPEECH] {json.dumps(r)[:800]}"
            if line.startswith("GEN_AVATAR:"):
                r = await media.generate_avatar(line[11:].strip())
                return f"[GEN_AVATAR] {json.dumps(r)[:800]}"

            if line.startswith("LIST_SKILLS:"):
                return skills.list_skills()
            if line.startswith("GET_SKILL:"):
                return skills.get_skill(line[10:].strip())
            if line.startswith("SAVE_SKILL:"):
                name, body = skills.parse_save_spec(line[11:].strip())
                return skills.save_skill(name, body)
            if line.startswith("DELETE_SKILL:"):
                return skills.delete_skill(line[13:].strip())

            if line.startswith("LIST_LISTS:"):
                return lists.list_all()
            if line.startswith("GET_LIST:"):
                return lists.get_list(line[9:].strip())
            if line.startswith("CREATE_LIST:"):
                name, items = lists.parse_create_spec(line[12:].strip())
                return lists.create_list(name, items)
            if line.startswith("ADD_LIST:"):
                name, items = lists.parse_create_spec(line[9:].strip())
                return lists.add_items(name, items)

            if line.startswith("READ_LIFEOS:"):
                return self._read_lifeos(line[12:].strip())
            if line.startswith("UPDATE_LEAD:"):
                return self._update_lead(line[12:].strip())
            if line.startswith("CREATE_TASK:"):
                return self._create_task(line[12:].strip())
            if line.startswith("REMEMBER_FACT:"):
                return self._remember_fact(line[14:].strip())
            if line.startswith("DRAFT_EMAIL:"):
                return self._draft_email(line[12:].strip())
            if line.startswith("NOTIFY:"):
                msg = line[7:].strip()
                self.pending_side_effects.append({"type": "notify", "message": msg})
                return f"[Notification queued] {msg}"
        except Exception as e:
            return f"[Tool error] {e}"
        return f"[Unknown tool] {line}"

    def _read_lifeos(self, key: str) -> str:
        data = self.lifeos_data.get(key.strip(), {})
        if not data and self.memory:
            if key.strip() == "goals":
                data = self.memory.get_goals()
            elif key.strip() in ("crm", "leads"):
                data = self.memory.get_leads()
        if not data:
            return f"[READ_LIFEOS: {key}] No data (frontend /sync first)."
        return f"[READ_LIFEOS: {key}] {json.dumps(data, ensure_ascii=False)[:2000]}"

    def _update_lead(self, spec: str) -> str:
        params = _kv(spec)
        self.pending_side_effects.append({"type": "update_lead", **params})
        return f"[UPDATE_LEAD] Queued for {params.get('name', '?')}: {params}"

    def _create_task(self, spec: str) -> str:
        params = _kv(spec)
        self.pending_side_effects.append({"type": "create_task", **params})
        return f"[CREATE_TASK] Queued: {params.get('text', '?')} [{params.get('priority', 'normal')}]"

    def _remember_fact(self, spec: str) -> str:
        params = _kv(spec)
        key, val = params.get("key", ""), params.get("value", "")
        if self.memory and key:
            self.memory.learn(key, val)
        return f"[REMEMBER_FACT] Stored: {key} = {val}"

    def _draft_email(self, spec: str) -> str:
        params = _kv(spec)
        self.pending_side_effects.append({"type": "draft_email", **params})
        return f"[DRAFT_EMAIL] Draft for {params.get('to', '?')}: {params.get('subject', '?')}"


TOOL_PREFIXES = (
    "SEARCH_WEB:", "BROWSE_URL:", "SCRAPE_PAGE:", "CLICK:", "FILL_FORM:", "SCREENSHOT:",
    "OPEN_BROWSER:",
    "FS_LS:", "FS_READ:", "FS_WRITE:", "FS_DELETE:",
    "LIST_DIR:", "READ_FILE:", "WRITE_FILE:", "DELETE_FILE:",
    "RUN_CMD:", "RUN_PYTHON:",
    "GEN_IMAGE:", "GEN_VIDEO:", "GEN_MUSIC:", "GEN_SPEECH:", "GEN_AVATAR:",
    "LIST_SKILLS:", "GET_SKILL:", "SAVE_SKILL:", "DELETE_SKILL:",
    "LIST_LISTS:", "GET_LIST:", "CREATE_LIST:", "ADD_LIST:",
    "READ_LIFEOS:", "UPDATE_LEAD:", "CREATE_TASK:", "REMEMBER_FACT:", "DRAFT_EMAIL:", "NOTIFY:",
)


class TaskPlanner:
    def __init__(self, router: ModelRouter, memory: ErebusMemory):
        self.router = router
        self.memory = memory
        self.executor = ToolExecutor(memory=memory)

    def set_lifeos_data(self, data: dict):
        self.executor.lifeos_data = data

    def _extract_tool_line(self, response: str) -> str | None:
        for line in response.splitlines():
            line = line.strip()
            if any(line.startswith(p) for p in TOOL_PREFIXES):
                return line
        return None

    def _extract_done(self, response: str) -> str | None:
        for line in response.splitlines():
            line = line.strip()
            if line.startswith("DONE:"):
                return line[5:].strip()
        return None

    async def run_task(self, task: str, context: str = "") -> AsyncGenerator[dict, None]:
        history = []
        system = PLANNER_SYSTEM
        if context:
            history.append({"role": "user", "content": f"[Context]\n{context}"})
            history.append({"role": "assistant", "content": "Understood. Ready."})

        user_msg = f"Task: {task}"
        self.memory.remember("user", user_msg)
        self.executor.pending_side_effects = []

        for step in range(1, MAX_STEPS + 1):
            try:
                response = await self.router.route(
                    message=user_msg, mode="reasoning", system=system, history=history,
                )
            except Exception as e:
                yield {"type": "error", "message": str(e)}
                return

            self.memory.extract_and_learn(response)

            done_answer = self._extract_done(response)
            if done_answer:
                self.memory.remember("assistant", done_answer)
                yield {
                    "type": "done",
                    "answer": done_answer,
                    "steps": step,
                    "model": self.router.get_active_model(),
                    "side_effects": list(self.executor.pending_side_effects),
                }
                return

            tool_line = self._extract_tool_line(response)
            if tool_line:
                tool_result = await self.executor.execute(tool_line)
                yield {
                    "type": "step",
                    "step": step,
                    "thought": response.replace(tool_line, "").strip()[:300],
                    "tool": tool_line[:200],
                    "result": tool_result[:1200],
                }
                history.append({"role": "assistant", "content": response})
                history.append({"role": "user", "content": f"[Tool result]\n{tool_result}"})
                user_msg = "Continue."
            else:
                self.memory.remember("assistant", response)
                yield {
                    "type": "done",
                    "answer": response,
                    "steps": step,
                    "model": self.router.get_active_model(),
                    "side_effects": list(self.executor.pending_side_effects),
                }
                return

        last = history[-1]["content"] if history else "No result."
        yield {
            "type": "done",
            "answer": f"Reached step limit. Last observation: {last[:400]}",
            "steps": MAX_STEPS,
            "model": self.router.get_active_model(),
            "side_effects": list(self.executor.pending_side_effects),
        }

    async def run_task_sync(self, task: str, context: str = "") -> dict:
        steps = []
        answer = None
        model = self.router.get_active_model()
        side = []
        async for event in self.run_task(task, context):
            if event["type"] == "step":
                steps.append(event)
            elif event["type"] == "done":
                answer = event["answer"]
                model = event.get("model", model)
                side = event.get("side_effects") or []
            elif event["type"] == "error":
                return {"error": event["message"], "steps": steps}
        return {"answer": answer, "steps": steps, "model": model, "side_effects": side}
