{"content":"# ============================================================
# Erebus Advanced Agent — FastAPI Backend v3
# Endpoints: /health /wake /capabilities /chat /task /stream
#            /memory /sync /execute /tools /hermes
# ============================================================

from __future__ import annotations

import json
import os
import webbrowser
from typing import AsyncGenerator, Optional

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse
from pydantic import BaseModel

from runtime.env_loader import load_erebus_env, media_keys, snapshot_keys
from agent.router import ModelRouter
from agent.memory import ErebusMemory
from agent.core import ErebusAgent
from agent.planner import TaskPlanner, ToolExecutor
from agent.tools import browser, files, lists, media, skills
from utils.code_executor import run_command, run_python

# Load all envs before router constructs
load_erebus_env()

app = FastAPI(title="Erebus Advanced Agent", version="3.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

_router = ModelRouter()
_memory = ErebusMemory()
_agent = ErebusAgent(_router, _memory)
_planner = TaskPlanner(_router, _memory)
_direct = ToolExecutor(memory=_memory)


class ChatRequest(BaseModel):
    message: str
    mode: str = "reasoning"
    system: str = ""
    history: list = []


class TaskRequest(BaseModel):
    task: str
    context: str = ""


class SyncRequest(BaseModel):
    crm: list = []
    tasks: list = []
    goals: list = []
    calendar: list = []
    contacts: list = []


class ExecuteRequest(BaseModel):
    action: str
    path: Optional[str] = ""
    content: Optional[str] = ""
    cmd: Optional[str] = ""
    url: Optional[str] = ""
    prompt: Optional[str] = ""
    text: Optional[str] = ""
    name: Optional[str] = ""
    items: Optional[str] = ""
    selector: Optional[str] = ""
    body: Optional[str] = ""


class MemoryRequest(BaseModel):
    key: str
    value: str


class HermesRequest(BaseModel):
    """Hermes bridge — same payload Hermes can POST."""
    goal: str
    context: str = ""
    mode: str = "task"  # task | chat


@app.get("/health")
async def health():
    return {
        "status": "online",
        "version": "3.0.0",
        "model": _router.get_active_model(),
        "models_available": _router.available_models(),
        "memory": _memory.stats(),
        "media": media_keys(),
        "browser": await browser.status(),
    }


@app.get("/wake")
async def wake():
    return await _agent.wake()


@app.get("/capabilities")
async def capabilities():
    return {
        "chat": True,
        "reasoning": True,
        "learning": True,
        "browser": {
            "search": True,
            "browse": True,
            "scrape": True,
            "click_fill_screenshot": (await browser.status()).get("online", False),
            "agent_url": browser.browser_base(),
        },
        "files": {
            "virtual_fs": True,
            "real_disk_sandbox": True,
            "shell": True,
            "python": True,
        },
        "media": media_keys(),
        "skills": True,
        "lists": True,
        "models": _router.capabilities(),
        "keys_present": snapshot_keys(),
        "endpoints": [
            "/health", "/wake", "/capabilities", "/chat", "/task", "/stream",
            "/memory", "/memory/learn", "/sync", "/execute", "/tools", "/hermes",
        ],
    }


@app.post("/chat")
async def chat(req: ChatRequest):
    try:
        return await _agent.reason(
            message=req.message,
            mode=req.mode,
            extra_history=req.history or None,
        )
    except Exception as e:
        return {
            "response": _router.local_fallback(req.message),
            "model": "local",
            "error": str(e),
        }


@app.post("/task")
async def run_task(req: TaskRequest):
    try:
        return await _planner.run_task_sync(req.task, req.context)
    except Exception as e:
        return {"error": str(e), "steps": []}


@app.post("/stream")
async def stream_task(req: TaskRequest):
    async def event_stream() -> AsyncGenerator[str, None]:
        async for event in _planner.run_task(req.task, req.context):
            yield f"data: {json.dumps(event)}\n\n"
        yield "data: [DONE]\n\n"

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Access-Control-Allow-Origin": "*",
        },
    )


@app.post("/hermes")
async def hermes_bridge(req: HermesRequest):
    """Entry point for Hermes → Erebus dispatch."""
    if req.mode == "chat":
        out = await _agent.reason(req.goal, mode="reasoning")
        return {"ok": True, "mode": "chat", **out}
    result = await _planner.run_task_sync(req.goal, req.context)
    return {"ok": True, "mode": "task", **result}


@app.post("/sync")
async def sync_context(req: SyncRequest):
    lifeos_data = {
        "crm": req.crm,
        "tasks": req.tasks,
        "goals": req.goals,
        "calendar": req.calendar,
        "contacts": req.contacts,
    }
    _memory.sync_context(goals=req.goals, leads=req.crm)
    _planner.set_lifeos_data(lifeos_data)
    _direct.lifeos_data = lifeos_data
    return {"status": "synced", "counts": {k: len(v) for k, v in lifeos_data.items()}}


@app.get("/memory")
async def get_memory():
    return {
        "stats": _memory.stats(),
        "facts": _memory.get_facts(50),
        "session": _memory.get_session(20),
        "goals": _memory.get_goals(),
        "leads": _memory.get_leads(),
    }


@app.post("/memory/learn")
async def learn_fact(req: MemoryRequest):
    _memory.learn(req.key, req.value)
    return {"status": "learned", "key": req.key}


@app.delete("/memory/session")
async def clear_session():
    _memory.clear_session()
    return {"status": "cleared"}


@app.get("/tools")
async def tools_catalog():
    return {
        "prefixes": [
            "SEARCH_WEB", "BROWSE_URL", "SCRAPE_PAGE", "CLICK", "FILL_FORM", "SCREENSHOT", "OPEN_BROWSER",
            "FS_LS", "FS_READ", "FS_WRITE", "FS_DELETE", "LIST_DIR", "READ_FILE", "WRITE_FILE",
            "RUN_CMD", "RUN_PYTHON",
            "GEN_IMAGE", "GEN_VIDEO", "GEN_MUSIC", "GEN_SPEECH", "GEN_AVATAR",
            "LIST_SKILLS", "GET_SKILL", "SAVE_SKILL",
            "LIST_LISTS", "GET_LIST", "CREATE_LIST", "ADD_LIST",
            "READ_LIFEOS", "UPDATE_LEAD", "CREATE_TASK", "REMEMBER_FACT", "DRAFT_EMAIL", "NOTIFY",
        ],
        "skills": skills.list_skills(),
        "lists": lists.list_all(),
        "media": media.capabilities(),
        "browser": await browser.status(),
    }


@app.post("/execute")
async def execute(req: ExecuteRequest):
    """Direct tool execution — used by UI and Hermes for one-shot actions."""
    try:
        a = (req.action or "").strip()

        # legacy + expanded
        if a in ("write_file", "WRITE_FILE"):
            return {"result": files.real_write(req.path or "", req.content or "")}
        if a in ("read_file", "READ_FILE"):
            return {"result": files.real_read(req.path or "")}
        if a in ("list_dir", "LIST_DIR"):
            return {"result": files.real_list_dir(req.path or "")}
        if a in ("delete_file", "DELETE_FILE"):
            return {"result": files.real_delete(req.path or "")}
        if a in ("run_command", "RUN_CMD"):
            return {"result": run_command(req.cmd or "")}
        if a in ("run_python", "RUN_PYTHON"):
            return {"result": run_python(req.content or req.cmd or "")}
        if a in ("open_browser", "OPEN_BROWSER"):
            webbrowser.open(req.url or "")
            return {"result": f"Opened: {req.url}"}

        if a in ("fs_ls", "FS_LS"):
            return {"result": files.vfs().ls(req.path or "/")}
        if a in ("fs_read", "FS_READ"):
            return {"result": files.vfs().read(req.path or "")}
        if a in ("fs_write", "FS_WRITE"):
            return {"result": files.vfs().write(req.path or "", req.content or "")}
        if a in ("fs_delete", "FS_DELETE"):
            return {"result": files.vfs().delete(req.path or "")}

        if a in ("search_web", "SEARCH_WEB"):
            return {"result": await browser.search(req.prompt or req.text or "")}
        if a in ("browse_url", "BROWSE_URL"):
            return {"result": await browser.browse_url(req.url or "")}
        if a in ("scrape_page", "SCRAPE_PAGE"):
            return {"result": await browser.scrape(req.url or "", req.selector)}
        if a in ("click", "CLICK"):
            return {"result": await browser.click(selector=req.selector, text=req.text)}
        if a in ("screenshot", "SCREENSHOT"):
            return {"result": await browser.screenshot()}

        if a in ("gen_image", "GEN_IMAGE"):
            return {"result": await media.generate_image(req.prompt or req.text or "")}
        if a in ("gen_video", "GEN_VIDEO"):
            return {"result": await media.generate_video(req.prompt or req.text or "")}
        if a in ("gen_music", "GEN_MUSIC"):
            return {"result": await media.generate_music(req.prompt or req.text or "")}
        if a in ("gen_speech", "GEN_SPEECH"):
            return {"result": await media.generate_speech(req.text or req.prompt or "")}
        if a in ("gen_avatar", "GEN_AVATAR"):
            return {"result": await media.generate_avatar(req.text or req.prompt or "")}

        if a in ("list_skills", "LIST_SKILLS"):
            return {"result": skills.list_skills()}
        if a in ("get_skill", "GET_SKILL"):
            return {"result": skills.get_skill(req.name or "")}
        if a in ("save_skill", "SAVE_SKILL"):
            return {"result": skills.save_skill(req.name or "", req.body or req.content or "")}

        if a in ("list_lists", "LIST_LISTS"):
            return {"result": lists.list_all()}
        if a in ("get_list", "GET_LIST"):
            return {"result": lists.get_list(req.name or "")}
        if a in ("create_list", "CREATE_LIST"):
            return {"result": lists.create_list(req.name or "", lists.parse_items(req.items or ""))}
        if a in ("add_list", "ADD_LIST"):
            return {"result": lists.add_items(req.name or "", lists.parse_items(req.items or ""))}

        # free-form tool line
        if a.startswith("TOOL:"):
            return {"result": await _direct.execute(a[5:].strip())}
        if ":" in a and a.split(":", 1)[0].isupper():
            return {"result": await _direct.execute(a)}

        raise HTTPException(400, f"Unknown action: {req.action}")
    except HTTPException:
        raise
    except Exception as e:
        return {"result": f"Error: {e}"}


if __name__ == "__main__":
    import uvicorn

    port = int(os.getenv("FASTAPI_PORT", 8000))
