{"content":""""
Hermes → Erebus HTTP bridge helpers.

Usage from Hermes terminal:
  curl -s http://127.0.0.1:8000/wake
  curl -s -X POST http://127.0.0.1:8000/hermes -H "Content-Type: application/json" -d "{\"goal\":\"status\",\"mode\":\"chat\"}"
  curl -s -X POST http://127.0.0.1:8000/task -H "Content-Type: application/json" -d "{\"task\":\"LIST_SKILLS then summarize\"}"
"""
from __future__ import annotations

import json
import urllib.request


BASE = "http://127.0.0.1:8000"


def _post(path: str, payload: dict) -> dict:
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        f"{BASE}{path}",
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=120) as r:
        return json.loads(r.read().decode("utf-8"))


def wake() -> dict:
    with urllib.request.urlopen(f"{BASE}/wake", timeout=10) as r:
        return json.loads(r.read().decode("utf-8"))


def chat(message: str) -> dict:
    return _post("/chat", {"message": message, "mode": "reasoning"})


def task(goal: str, context: str = "") -> dict:
    return _post("/task", {"task": goal, "context": context})


def hermes(goal: str, context: str = "", mode: str = "task") -> dict:
    return _post("/hermes", {"goal": goal, "context": context, "mode": mode})


def execute(action: str, **kwargs) -> dict:
    return _post("/execute", {"action": action, **kwargs})


if __name__ == "__main__":
    print(json.dumps(wake(), indent=2))
